def add_batch(batch) -> Union[torch.Tensor, np.ndarray]:
    # Base case: if batch is not a tuple, list, dict, tensor, or array, convert it to a tensor
    if not isinstance(batch, (tuple, list, dict, torch.Tensor, np.ndarray)):
        batch = torch.as_tensor(batch)

    # If batch is a tensor or array, add a new dimension at index 0
    if isinstance(batch, (torch.Tensor, np.ndarray)):
        return batch[np.newaxis]

    # If batch is a tuple or list, recursively apply add_batch to each element
    if isinstance(batch, (tuple, list)):
        return [add_batch(b) for b in batch]

    # If batch is a dict, create a new dotdict and recursively apply add_batch to each value
    if isinstance(batch, dict):
        return dotdict({k: add_batch(v) for k, v in batch.items()})
